      function evtTailPanel(){
        const data=dashboardData.ihsg,series=(data?.series||[]).filter(row=>Number.isFinite(Number(row.price))&&Number(row.price)>0);
        if(!data?.ok||series.length<30)return section('IHSG · EVT tail-risk explorer','<div class="market-data-placeholder"><div><strong>Snapshot IHSG belum cukup untuk probe EVT</strong>Panel memerlukan seri penutupan harian yang valid.</div></div>','DATA REQUIRED','market-wide');
        const obs=series.map((row,index)=>({date:row.date,price:Number(row.price)})).sort((a,b)=>a.date.localeCompare(b.date));
        const losses=obs.slice(1).map((row,index)=>({date:row.date,value:-Math.log(row.price/obs[index].price)})).filter(row=>Number.isFinite(row.value));
        const sorted=losses.map(row=>row.value).sort((a,b)=>a-b),quantile=p=>{const pos=(sorted.length-1)*p,lo=Math.floor(pos),hi=Math.ceil(pos);return sorted[lo]+(sorted[hi]-sorted[lo])*(pos-lo)},q95=quantile(.95),tailCount=losses.filter(row=>row.value>q95).length;
        const min=Math.floor(Math.min(...sorted)*100)/100,max=Math.ceil(Math.max(...sorted)*100)/100,span=max-min||1,bins=36,counts=Array(bins).fill(0),binWidth=span/bins;
        losses.forEach(row=>{const i=Math.min(bins-1,Math.max(0,Math.floor((row.value-min)/binWidth)));counts[i]++});
        const W=1120,H=390,L=66,R=24,T=26,B=62,plotW=W-L-R,plotH=H-T-B,peak=Math.max(1,...counts),x=v=>L+(v-min)/span*plotW,y=v=>T+plotH-v/peak*plotH,barW=plotW/bins;
        let marks='';counts.forEach((count,i)=>{const x0=L+i*barW,center=min+(i+.5)*binWidth,tail=center>=q95,color=tail?'#f0475a':'#5d616b',range=`${((min+i*binWidth)*100).toFixed(2)}%–${((min+(i+1)*binWidth)*100).toFixed(2)}%`;marks+=`<rect data-evt-bin="true" data-range="${range}" data-count="${count}" data-tail="${tail?'yes':'no'}" x="${(x0+1).toFixed(1)}" y="${y(count).toFixed(1)}" width="${Math.max(1,barW-2).toFixed(1)}" height="${(T+plotH-y(count)).toFixed(1)}" rx="2" fill="${color}" opacity="${tail?'.94':'.78'}"><title>${range} · ${count} sesi${tail?' · ekor di atas p95':''}</title></rect>`});
        const grid=[0,.25,.5,.75,1].map(f=>{const yy=T+plotH*(1-f),value=Math.round(peak*f);return `<line x1="${L}" y1="${yy}" x2="${W-R}" y2="${yy}" stroke="#4a4e57" stroke-opacity=".5" stroke-dasharray="4 5"/><text x="${L-10}" y="${yy+4}" fill="#8a8f98" font-size="11" text-anchor="end">${value}</text>`}).join('');
        const ticks=[min,min+span/4,min+span/2,min+span*3/4,max].map(v=>`<line x1="${x(v)}" y1="${T+plotH}" x2="${x(v)}" y2="${T+plotH+5}" stroke="#8a8f98"/><text x="${x(v)}" y="${T+plotH+24}" fill="#8a8f98" font-size="11" text-anchor="middle">${(v*100).toFixed(0)}%</text>`).join('');
        const threshold=`<line x1="${x(q95)}" y1="${T}" x2="${x(q95)}" y2="${T+plotH}" stroke="#f2c14e" stroke-width="2" stroke-dasharray="7 5"><title>Ambang empiris p95: ${(q95*100).toFixed(2)}%</title></line><text x="${Math.min(W-R-4,x(q95)+7)}" y="${T+14}" fill="#f2c14e" font-size="12" font-weight="700">p95 ${(q95*100).toFixed(2)}%</text>`;
        const chart=`<div class="evt-chart-wrap"><svg class="evt-chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="Histogram kerugian harian IHSG, ${losses.length} return harian. Area ekor di atas ambang empiris persentil 95 disorot.">${grid}${marks}${threshold}${ticks}<text x="${L+plotW/2}" y="${H-10}" fill="#8a8f98" font-size="12" text-anchor="middle">Kerugian harian (−log return; negatif berarti sesi naik)</text><text x="17" y="${T+plotH/2}" fill="#8a8f98" font-size="11" text-anchor="middle" transform="rotate(-90 17 ${T+plotH/2})">Jumlah sesi</text></svg></div>`;
        const probeMatches=data.coverage_end==='2026-09-24'&&Number(data.observation_count)===708&&data.retrieved_at==='2026-09-27T16:43:12.252647+00:00';
        const caveat=probeMatches?'Fit GPD ξ=+0.267 memakai 36 exceedances pada snapshot ini. Bootstrap blok 5 sesi menghasilkan interval 95% −0.494…+0.870 yang melintasi nol; parameter ekor masih sangat tidak pasti. Histogram dan ambang empiris dihitung dari snapshot aktif; statistik GPD hanya ditampilkan bila provenance snapshot tepat cocok dengan probe.':'Snapshot berbeda dari run EVT notebook 2026-09-29; fit GPD disembunyikan agar angka lama tidak tampak sebagai hasil snapshot baru. Jalankan ulang probe sebelum menampilkan estimasi parametris.';
        const body=`<div class="evt-overview"><div class="evt-stat"><small>Daily Return</small><strong>${losses.length} sesi</strong></div><div class="evt-stat"><small>Ambang loss empiris p95</small><strong>${(q95*100).toFixed(2)}%</strong></div><div class="evt-stat"><small>Observasi di atas p95</small><strong>${tailCount}</strong></div><div class="evt-stat"><small>Source Range</small><strong>${escapeHTML(obs[0].date)} → ${escapeHTML(obs.at(-1).date)}</strong></div></div>${probeMatches?`<div class="evt-overview"><div class="evt-stat"><small>GPD shape ξ · fit p95</small><strong>+0.267</strong></div><div class="evt-stat"><small>Bootstrap interval 95% ξ</small><strong>−0.494 … +0.870</strong></div><div class="evt-stat"><small>Bootstrap</small><strong>300 blok × 5 sesi</strong></div><div class="evt-stat"><small>Sensitivitas ambang Δξ</small><strong>0.313</strong></div></div>`:''}`;
        const surface=dashboardData.evt_surface,surfaceView=surface?.ok&&surface.source_retrieved_at===data.retrieved_at?evtSurfaceMarkup(surface):`<div class="market-data-placeholder"><div><strong>Grid surface belum cocok dengan snapshot aktif</strong>Jalankan <code>scripts/build_ihsg_evt_tail_surface.m</code> di MATLAB untuk membangun ulang data surface dari snapshot yang sama.</div></div>`;
        const surfaceExplanation=`<div class="evt-surface-explanation"><strong>Cara membaca surface 3D.</strong> Sumbu X menunjukkan akhir bulan, Y menunjukkan kuantil empiris (p90–p97,5), dan Z serta warna menunjukkan besarnya loss harian pada jendela 252 sesi sebelumnya. Permukaan yang meninggi berarti ambang loss historis pada jendela itu membesar; ini deskripsi ekor return masa lalu, bukan probabilitas crash atau ramalan. Data bulanan diperbarui dari snapshot MATLAB yang sama dengan interaksi kamera live.</div>`;
        const histogramNote=`<p class="evt-note"><b>Cara membaca histogram.</b> Ini melengkapi surface: batang menunjukkan sebaran seluruh ${losses.length} return harian, ekor merah berada di atas ambang empiris p95 ${(q95*100).toFixed(2)}%, dan garis amber hanya penanda ambang—bukan stop atau sinyal. ${escapeHTML(caveat)} Belum diuji out-of-sample atau untuk keputusan trading. Sumber: snapshot lokal Sectors.app · IHSG harian · ${Number(data.observation_count)} penutupan.</p>`;
        const histogramPanel=`<section class="evt-secondary-visual"><div class="evt-visual-heading"><div><h3>Distribusi return harian · konteks ekor</h3><p>Histogram seluruh sesi, dengan ambang p95 dan observasi ekor ditandai.</p></div><span class="evt-visual-meta">${losses.length} return · p95 ${(q95*100).toFixed(2)}%</span></div>${chart}${histogramNote}</section>`;
        const displayBody=`${body}<div class="evt-visual-stack"><section class="evt-primary-visual"><div class="evt-visual-heading"><div><h3>Surface tail-loss historis · MATLAB live</h3><p>Visualisasi utama: evolusi ambang loss empiris IHSG pada rolling window 252 sesi.</p></div><span class="evt-visual-meta">${surface?.ok?'24 akhir bulan · 4 kuantil · sudut kamera tersinkron':'GRID BELUM TERSEDIA'}</span></div>${surfaceView}${surfaceExplanation}</section>${histogramPanel}</div>`;
        return section('IHSG · EVT tail-risk explorer',displayBody,'INTERAKTIF · MATLAB DATA · BUKAN PROBABILITAS CRASH','market-wide evt-panel');
      }
      function marketRegimePanel(compact=false){
        const data=dashboardData.ihsg,series=(data?.series||[]).filter(item=>Number.isFinite(Number(item.price))&&Number(item.price)>0);
        const unavailable=message=>section('Market regime · IHSG',`<div class="market-data-placeholder"><div><strong>Regime belum dapat dihitung</strong>${message}</div></div>`,'INSUFFICIENT EVIDENCE');
        if(!data?.ok)return unavailable('Snapshot IHSG lokal belum tersedia.');
        if(series.length<201)return unavailable(`Perlu minimal 201 penutupan harian; saat ini tersedia ${series.length}.`);
        const prices=series.map(item=>Number(item.price)),last=prices.at(-1),mean=(start,end)=>prices.slice(start,end).reduce((sum,value)=>sum+value,0)/(end-start);
        const sma50=mean(prices.length-50,prices.length),sma200=mean(prices.length-200,prices.length);
        const label=last>sma200&&sma50>sma200?'Tren menguat':last<sma200&&sma50<sma200?'Tren melemah':'Tren campuran';
        const color=label==='Tren menguat'?'#22c07a':label==='Tren melemah'?'#f0475a':'#f2c14e';
        const returns=[];for(let i=1;i<prices.length;i++)returns.push(prices[i]/prices[i-1]-1);
        const windowVol=[];for(let end=20;end<=returns.length;end++){const window=returns.slice(end-20,end),avg=window.reduce((sum,value)=>sum+value,0)/window.length,variance=window.reduce((sum,value)=>sum+(value-avg)**2,0)/(window.length-1);windowVol.push(Math.sqrt(variance*252));}
        if(!windowVol.length)return unavailable('Riwayat return belum cukup untuk menghitung volatilitas 20 sesi.');
        const currentVol=windowVol.at(-1),rank=100*windowVol.filter(value=>value<=currentVol).length/windowVol.length,marker=Math.max(0,Math.min(100,rank));
        const volBand=rank<25?'relatif rendah':rank>75?'relatif tinggi':'sekitar tengah';
        if(compact)return section('Market Regime · IHSG',`<div class="dashboard-summary-kpi" style="color:var(--tk-${label==='Tren menguat'?'up':label==='Tren melemah'?'down':'flat'},${color})">${label}</div><div class="dashboard-meta">Close & SMA 50 dibanding SMA 200</div><div class="dashboard-summary-pair"><span>20-Session Volatility</span><b>${(currentVol*100).toFixed(1)}% p.a.</b></div><div class="market-regime-vol-track" role="img" aria-label="Persentil volatilitas ${rank.toFixed(0)} dari 100"><span class="market-regime-vol-marker" style="left:${marker.toFixed(1)}%"></span></div><div class="market-regime-vol-labels"><span>Low</span><span>p${rank.toFixed(0)} · ${volBand}</span><span>High</span></div><p class="dashboard-meta">${escapeHTML(data.coverage_end)} · baseline deskriptif, bukan forecast.</p>`,btn('Market Detail','go-market'),'dashboard-regime-summary');
        const date=escapeHTML(data.coverage_end||series.at(-1).date),fmt=value=>Number(value).toLocaleString('id-ID',{minimumFractionDigits:2,maximumFractionDigits:2});
        const body=`<div class="market-regime"><div class="market-regime-state" style="--regime-color:${color}"><strong>${label}</strong><small>Aturan tren: posisi IHSG dan SMA 50 sesi dibandingkan SMA 200 sesi.</small></div><div class="market-regime-metrics"><div><small>IHSG · ${date}</small><b>${fmt(last)}</b></div><div><small>SMA 50 Sessions</small><b>${fmt(sma50)}</b></div><div><small>SMA 200 Sessions</small><b>${fmt(sma200)}</b></div></div><div class="market-regime-vol"><div class="row"><b>20-Session Volatility</b><span>${currentVol.toLocaleString('id-ID',{style:'percent',maximumFractionDigits:1})} p.a. · ${volBand}</span></div><div class="market-regime-vol-track" role="img" aria-label="Volatilitas IHSG 20 sesi berada pada persentil ${rank.toFixed(0)} dibanding rolling history"><span class="market-regime-vol-marker" style="left:${marker.toFixed(1)}%"></span></div><div class="market-regime-vol-labels"><span>low · p0</span><span>p${rank.toFixed(0)} dari rolling history · tinggi p100</span></div></div><p class="note">Snapshot lokal Sectors.app · ${series.length} penutupan (${escapeHTML(data.coverage_start)}–${date}). Volatilitas = simpangan baku return 20 sesi disetahunkan; persentil dibandingkan jendela 20 sesi pada snapshot yang sama.</p><p class="note">Label tren adalah baseline teknikal deskriptif, bukan klasifikasi tervalidasi atau ramalan. “Campuran” berarti arah harga dan susunan SMA tidak sejalan.</p></div>`;
        return section('Market regime · IHSG',body,'BASELINE DESKRIPTIF · BUKAN FORECAST');
      }
      function currentScreenerRegime(){
        const series=(dashboardData.ihsg?.series||[]).filter(item=>Number.isFinite(Number(item.price))&&Number(item.price)>0);
        if(series.length<201)return 'Belum dihitung';
        const prices=series.map(item=>Number(item.price)),last=prices.at(-1);
        const sma50=prices.slice(-50).reduce((sum,value)=>sum+value,0)/50;
        const sma200=prices.slice(-200).reduce((sum,value)=>sum+value,0)/200;
        return last>sma200&&sma50>sma200?'Tren menguat':last<sma200&&sma50<sma200?'Tren melemah':'Tren campuran';
      }
      function screenerSectorMap(){
        const map=new Map();
        (dashboardData.sectorHeatmap?.sectors||[]).forEach(row=>(row.member_tickers||[]).forEach(ticker=>map.set(String(ticker).toUpperCase(),String(row.sector||''))));
        return map;
      }
      function screenerSectorOptions(){
        const map=screenerSectorMap(),rows=screenerRows(),sectors=[...new Set([...map.values()].filter(Boolean))].sort((a,b)=>a.localeCompare(b,'id'));
        const unavailable=rows.some(row=>!map.has(String(row.ticker).toUpperCase()));
        return sectors.map(sector=>`<option value="${escapeHTML(sector)}" ${screenerFilters.sector===sector?'selected':''}>${escapeHTML(sector)}</option>`).join('')+(unavailable?`<option value="__unavailable__" ${screenerFilters.sector==='__unavailable__'?'selected':''}>Not Available</option>`:'');
      }
      function screenerTable(){
        const rows=screenerRows(),sectorMap=screenerSectorMap(),analysis=dashboardData.screener_analysis;
        const fresh=analysis?.formula_version==='foreign-net-buy-z20-v1'&&analysis?.as_of===dashboardData.ihsg?.coverage_end;
        const measured=new Map((fresh?analysis.rows:[]).map(row=>[row.ticker,row]));
        const pct=value=>Number.isFinite(value)?(value>0?'+':'')+(100*value).toFixed(2)+'%':'—';
        const rate=value=>Number.isFinite(value)?(100*value).toFixed(1)+'%':'—';
        const numeric=(value,unit='')=>Number.isFinite(value)?(value>0?'+':'')+value.toFixed(2)+unit:'—';
        return `<div class="screener-table-wrap"><table class="screener-table"><thead><tr><th scope="col">#</th><th scope="col">Ticker</th><th scope="col">Company</th><th scope="col" title="Net asing hari ini dibanding mean dan simpangan baku 20 sesi sebelumnya">Flow Strength<br><small>Foreign Z20</small></th><th scope="col" title="Jumlah event matang dan valid; n5 / n20, bukan jumlah hari histori">Sample<br><small>n5 / n20</small></th><th scope="col">5D Outcome<br><small>mean return</small></th><th scope="col">20D Outcome<br><small>mean return</small></th><th scope="col" title="Event 20D dengan return saham melebihi IHSG / n20">Hit Rate<br><small>beat IHSG · 20D</small></th><th scope="col" title="Wilson CI95 untuk Hit Rate; bukan interval return atau prediksi">Confidence Interval<br><small>95% · Hit Rate</small></th><th scope="col" title="Mean return saham 20D dikurangi mean IHSG pada tanggal yang sama, percentage points">Baseline Delta<br><small>vs IHSG · 20D · pp</small></th><th scope="col">Issuer Regime</th><th scope="col">Data / As of</th></tr></thead><tbody>${rows.map(function(row,index){
          const metric=measured.get(row.ticker),sector=sectorMap.get(String(row.ticker).toUpperCase())||'__unavailable__';
          const regime=metric?.regime?.label||'Belum dihitung',ci=metric?.hit_rate_ci95;
          const sample=metric?`${metric.sample_5d} / ${metric.sample_20d}${metric.sample_status==='SMALL_SAMPLE'?'<br><small>Small Sample</small>':metric.sample_status==='NO_MATURE_EVENTS'?'<br><small>No Matured Events</small>':''}`:'—';
          const excluded=metric?[`Sinyal terdeteksi: ${metric.event_count}`,`Sampel valid 5D / 20D: ${metric.sample_5d} / ${metric.sample_20d}`,...(metric.excluded.immature_20d?[`${metric.excluded.immature_20d} sinyal belum memiliki 20 sesi berikutnya pada cutoff data`]:[]),...(metric.excluded.invalid_20d?[`${metric.excluded.invalid_20d} sinyal tidak memiliki pasangan harga saham dan IHSG yang valid untuk 20D`]:[])].join(' · '):'Menunggu hasil perhitungan lokal.';
          const trend=metric?.regime||{},trendDetail=`Close ${trend.close??'—'} · SMA50 ${trend.sma50?.toFixed(2)??'—'} · SMA200 ${trend.sma200?.toFixed(2)??'—'}`;
          return `<tr data-action="open-issuer" data-ticker="${escapeHTML(row.ticker)}" data-sector="${escapeHTML(sector)}" data-regime="${escapeHTML(regime)}" tabindex="0"><td class="muted-cell">${index+1}</td><td class="ticker">${escapeHTML(row.ticker)}</td><td>${escapeHTML(row.company)}</td><td title="${escapeHTML(metric?.latest_net==null?'Net tidak tersedia':'Net asing Rp '+rupiahCompact(metric.latest_net))}">${numeric(metric?.flow_strength_z20,'σ')}</td><td title="${escapeHTML(excluded)}">${sample}</td><td>${pct(metric?.outcome_5d)}</td><td>${pct(metric?.outcome_20d)}</td><td title="${metric?.hit_count??0} dari ${metric?.sample_20d??0} event">${rate(metric?.hit_rate)}</td><td>${ci?`${rate(ci[0])} – ${rate(ci[1])}`:'—'}</td><td>${numeric(Number.isFinite(metric?.baseline_delta_20d)?metric.baseline_delta_20d*100:null,' pp')}</td><td title="${escapeHTML(trendDetail)}">${escapeHTML(regime)}</td><td class="muted-cell" title="${escapeHTML(sector==='__unavailable__'?'Sektor tidak tersedia':sector)}">${escapeHTML(metric?.as_of||'—')}<br><small>${metric?.data_quality==='VERIFIED'?'Snapshot lokal':'Data belum tersedia'}</small></td></tr>`;
        }).join('')}</tbody></table><p class="dashboard-meta" id="screener-empty-state" hidden>Tidak ada emiten yang cocok dengan filter saat ini.</p></div>`;
      }
      function screenerReportSection(analysis){
        if(!analysis?.ok)return section('Screener · Historical Calculation','<p>Hasil Screener tidak tersedia; tidak ada metrik yang diestimasi.</p>');
        const percent=value=>Number.isFinite(value)?(value*100).toFixed(2)+'%':'—';
        const methods=Object.entries(analysis.method||{}).filter(([key,value])=>typeof value==='string').map(([key,value])=>`<li><b>${escapeHTML(key)}:</b> ${escapeHTML(value)}</li>`).join('');
        const rows=analysis.rows.map(row=>`<tr><th scope="row">${escapeHTML(row.ticker)}</th><td>${row.sample_5d}/${row.sample_20d}</td><td>${percent(row.outcome_5d)}</td><td>${percent(row.outcome_20d)}</td><td>${percent(row.baseline_20d)}</td><td>${row.baseline_delta_20d==null?'—':(row.baseline_delta_20d*100).toFixed(2)+' pp'}</td><td>${row.hit_count}/${row.sample_20d}<br>${percent(row.hit_rate)}</td><td>${row.hit_rate_ci95?row.hit_rate_ci95.map(percent).join(' – '):'—'}</td><td>${escapeHTML(row.regime.label)}</td><td>${row.event_count} event · ${row.excluded.immature_20d||0} belum matang · ${row.excluded.invalid_20d||0} tidak valid<br>${escapeHTML(row.sample_status)}</td></tr>`).join('');
        return section('Screener · Foreign Flow Event Study & Issuer Regime',`<p>Formula ${escapeHTML(analysis.formula_version)} · ${escapeHTML(analysis.as_of)} · ${analysis.summary.computed_count}/${analysis.summary.issuer_count} emiten dihitung ulang dari snapshot lokal. Membership masing-masing emiten diperiksa melalui report yang hash-nya cocok; masalah metadata universe tetap dicatat: ${escapeHTML((analysis.issues||[]).join('; ')||'Tidak ada')}.</p><ul>${methods}</ul><div class="table-wrap"><table><thead><tr><th>Ticker</th><th>n5/n20</th><th>5D</th><th>20D</th><th>IHSG 20D</th><th>Delta 20D</th><th>Hit Rate</th><th>Wilson CI95</th><th>Stock Regime</th><th>Event / Exclusion</th></tr></thead><tbody>${rows}</tbody></table></div><ul>${(analysis.method.limitations||[]).map(value=>`<li>${escapeHTML(value)}</li>`).join('')}</ul><p>Fingerprint input: <code>${escapeHTML(analysis.source_fingerprint)}</code>. Notebook reproduksi: notebooks/screener-flow-event-study.ipynb. Angka adalah hasil studi event historis, bukan klaim strategi tervalidasi.</p>`,'DERIVED METRICS · DESKRIPTIF');
      }
      function applyScreenerFilters(){
        if(page!=='screener')return;
        const query=screenerFilters.query.trim().toLocaleLowerCase(),rows=[...main.querySelectorAll('.screener-table tbody tr')];let visible=0;
        rows.forEach(function(row){const matchQuery=!query||row.textContent.toLocaleLowerCase().includes(query),matchSector=!screenerFilters.sector||row.dataset.sector===screenerFilters.sector,matchRegime=!screenerFilters.regime||row.dataset.regime===screenerFilters.regime;row.hidden=!(matchQuery&&matchSector&&matchRegime);if(!row.hidden)visible++});
        const count=main.querySelector('#screener-result-count');if(count)count.textContent=`Menampilkan ${visible} dari ${rows.length} emiten`;
        const empty=main.querySelector('#screener-empty-state');if(empty)empty.hidden=visible!==0;
      }
